        if let Some(x) = args.OBSERVER_ID { builder.add_OBSERVER_ID(x); }
        builder.add_SAMPLE_COUNT(args.SAMPLE_COUNT);
        if let Some(x) = args.STATION_ID { builder.add_STATION_ID(x); }
